function lineObj(a, b, mat = matBlack) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b]);
  return new THREE.Line(g, mat);
}

function dashedLine(group, a, b, pieces, dashFrac = 0.55) {
  const v = new THREE.Vector3().subVectors(b, a);
  for (let i = 0; i < pieces; i++) {
    const t0 = i / pieces;
    const t1 = t0 + dashFrac / pieces;
    const p0 = a.clone().addScaledVector(v, t0);
    const p1 = a.clone().addScaledVector(v, Math.min(t1, 1));
    group.add(lineObj(p0, p1));
  }
}

function wedgeMesh(tip, baseCenter, width) {
  const dir = new THREE.Vector3().subVectors(baseCenter, tip).normalize();
  const perp = new THREE.Vector3(-dir.y, dir.x, 0).multiplyScalar(width / 2);
  const verts = [
    tip.x, tip.y, tip.z,
    baseCenter.x + perp.x, baseCenter.y + perp.y, baseCenter.z,
    baseCenter.x - perp.x, baseCenter.y - perp.y, baseCenter.z
  ];
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(verts, 3));
  g.setIndex([0, 1, 2]);
  g.computeVertexNormals();
  return new THREE.Mesh(g, matWedge);
}

function skewPlane(width, depth, skew, y = 0, zc = 0) {
  const x0 = -width / 2, x1 = width / 2;
  const z0 = zc - depth / 2, z1 = zc + depth / 2;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute([
    x0, y, z0, x1, y, z0, x1 - skew, y, z1, x0 - skew, y, z1
  ], 3));
  g.setIndex([0, 1, 2, 0, 2, 3]);
  g.computeVertexNormals();
  return new THREE.Mesh(g, cyanMat.clone());
}

function hitPlane(x, y, w, h, name) {
