function lineObj(a, b, mat = matBlack) {
  return new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), mat);
}

function dashedLine(group, a, b, pieces, dashFrac = 0.48) {
  const v = new THREE.Vector3().subVectors(b, a);
  for (let i = 0; i < pieces; i++) {
    const p0 = a.clone().addScaledVector(v, i / pieces);
    const p1 = a.clone().addScaledVector(v, Math.min((i + dashFrac) / pieces, 1));
    group.add(lineObj(p0, p1));
  }
}

function wedgeMesh(narrow, broadCenter, width) {
  const dir = new THREE.Vector3().subVectors(broadCenter, narrow).normalize();
  const perp = new THREE.Vector3(-dir.y, dir.x, 0).multiplyScalar(width / 2);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute([
    narrow.x, narrow.y, narrow.z,
    broadCenter.x + perp.x, broadCenter.y + perp.y, broadCenter.z,
    broadCenter.x - perp.x, broadCenter.y - perp.y, broadCenter.z
  ], 3));
  g.setIndex([0, 1, 2]);
  g.computeVertexNormals();
  return new THREE.Mesh(g, matWedge);
}

function flatTrapezoidPlane() {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute([
    -0.55, -0.065, 0.025,
     0.48, -0.065, 0.025,
     0.38,  0.075, 0.025,
    -0.47,  0.075, 0.025
  ], 3));
  g.setIndex([0, 1, 2, 0, 2, 3]);
  g.computeVertexNormals();
  return new THREE.Mesh(g, cyanFlatMat.clone());
}

function molecularPlane(width, depth, skew) {
  const x0 = -width / 2, x1 = width / 2;
  const z0 = -depth / 2, z1 = depth / 2;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute([
    x0, 0, z0,
    x1, 0, z0,
    x1 - skew, 0, z1,
    x0 - skew, 0, z1
  ], 3));
  g.setIndex([0, 1, 2, 0, 2, 3]);
  g.computeVertexNormals();
  return new THREE.Mesh(g, cyanMolMat.clone());
}

function hitPlane(x, y, w, h, name) {
  const m = new THREE.Mesh(new THREE.PlaneGeometry(w, h), hitMat.clone());
