  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, len, radialSegments), mat);
  cyl.position.copy(a).add(b).multiplyScalar(0.5);
  cyl.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dvec.clone().normalize());
  group.add(cyl);
  return cyl;
}

