addStructLabel('hol', 'HO', -0.64, -0.69, { color: '#ee00a8', fontSize: '19px' });
addStructLabel('cou', 'CO<sub>2</sub>H', 0.80, 0.69, { color: '#00815d', fontSize: '18px' });
addStructLabel('col', 'CO<sub>2</sub>H', 0.80, -0.69, { color: '#00815d', fontSize: '18px' });
addStructLabel('plane', 'Symmetry plane', 1.20, 0.03, { color: '#111', fontSize: '20px' });

let currentMode = 'Structure + model';
let selectedType = null;

function worldFromStructLocal(v) {
  return v.clone().multiply(structureGroup.scale).add(structureGroup.position);
}

function setLayerRecursive(obj, layer) {
  obj.traverse(o => o.layers.set(layer));
}

function updateInteractiveLayers() {
  const structureActive = currentMode !== 'Model only';
  const modelActive = currentMode !== 'Structure only';
  structureHitTargets.forEach(o => setLayerRecursive(o, structureActive ? 0 : 1));
  modelInteractiveTargets.forEach(o => setLayerRecursive(o, modelActive ? 0 : 1));
}

function updateLabels() {
  const showStructureLabels = currentMode !== 'Model only';
  structLabels.forEach(entry => {
    entry.pos.copy(worldFromStructLocal(entry.userData.local));
    entry.div.style.opacity = showStructureLabels ? '1' : '0';
  });
}

function updateHighlight() {
  structHighlight.forEach(r => {
    r.visible = Boolean(selectedType) && r.userData.type === selectedType && currentMode !== 'Model only';
  });
  modelHighlight.forEach(s => {
    s.visible = Boolean(selectedType) && s.userData.type === selectedType && currentMode !== 'Structure only';
  });
}

function setButtonActive(i) {
  ['step0', 'step1', 'step2'].forEach((id, idx) => {
    const b = document.getElementById(id);
    if (b) b.classList.toggle('active', idx === i);
  });
}

function selectSubstituent(type, half) {
  selectedType = type;
  updateHighlight();
  const opposite = half === 'upper' ? 'lower' : 'upper';
  const slot = document.getElementById('selectSubstituent');
  if (slot) slot.innerHTML = `Selected ${half} ${type}; the faint yellow outlines mark it and the ${opposite} reflected partner.`;
}

function applyMode(mode, refit = true) {
  currentMode = mode;
  if (structureGroup.parent) scene.remove(structureGroup);
  if (modelGroup.parent) scene.remove(modelGroup);

  if (mode === 'Structure only') {
    structureGroup.position.set(0, 0, 0);
    structureGroup.scale.setScalar(1.05);
    modelGroup.position.set(0, 0, 0);
    scene.add(structureGroup);
  } else if (mode === 'Model only') {
    modelGroup.position.set(0, 0, 0);
    modelGroup.scale.setScalar(1.12);
    structureGroup.position.set(0, 0, 0);
    scene.add(modelGroup);
  } else {
    structureGroup.position.set(-1.65, 0.02, 0);
    structureGroup.scale.setScalar(0.76);
    modelGroup.position.set(1.18, 0.00, 0);
    modelGroup.scale.setScalar(0.92);
    scene.add(structureGroup);
    scene.add(modelGroup);
  }

  updateLabels();
  updateInteractiveLayers();
  updateHighlight();

  const select = document.getElementById('representationMode');
  if (select) select.value = mode;

  if (refit) {
    setCameraView({
      projection: 'orthographic',
      azimuthDeg: 90,
      elevationDeg: 7,
      rollDeg: 0,
      target: mode === 'Structure + model' ? [0, 0, 0.04] : [0, 0, 0.04],
      heightFraction: mode === 'Structure + model' ? 0.70 : 0.74,
      distanceScale: 1.35
    });
    updateLabels();
  }
}

const steps = [
  {
    title: 'Read the flat structural formula',
    narration: 'The two stereocenters are stacked vertically. A pale blue plane cuts halfway between them; each HO, H, and CO₂H group has a matching reflected partner.',
    state: { representationMode: 'Structure only' }
  },
  {
    title: 'Inspect the 3D model',
    narration: 'The ball-and-stick model uses tetrahedral bonds around each gray carbon. The same horizontal plane passes between the two central carbons.',
    state: { representationMode: 'Model only' }
  },
  {
    title: 'Compare drawing and model',
    narration: 'Side by side, the structural drawing and the 3D model show the same internal mirror plane, so the molecule is meso rather than chiral.',
    state: { representationMode: 'Structure + model' }
  }
];

window.goToStep = function goToStep(i) {
  const idx = Math.max(0, Math.min(steps.length - 1, i | 0));
  const step = steps[idx];
  selectedType = null;
  const slot = document.getElementById('selectSubstituent');
  if (slot) slot.innerHTML = 'Click HO, H, or CO₂H to highlight its reflected partner.';
  applyMode(step.state.representationMode, true);
  updateHighlight();
  setButtonActive(idx);
  const narr = document.getElementById('demoNarration');
  if (narr) narr.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
};

document.getElementById('representationMode')?.addEventListener('change', e => {
  selectedType = null;
  const slot = document.getElementById('selectSubstituent');
  if (slot) slot.innerHTML = 'Click HO, H, or CO₂H to highlight its reflected partner.';
  applyMode(e.target.value, true);
  updateHighlight();
  setButtonActive(e.target.value === 'Structure only' ? 0 : e.target.value === 'Model only' ? 1 : 2);
  const idx = e.target.value === 'Structure only' ? 0 : e.target.value === 'Model only' ? 1 : 2;
  const narr = document.getElementById('demoNarration');
  if (narr) narr.innerHTML = `<b>${steps[idx].title}</b><br>${steps[idx].narration}`;
});

document.getElementById('step0')?.addEventListener('click', () => window.goToStep(0));
document.getElementById('step1')?.addEventListener('click', () => window.goToStep(1));
document.getElementById('step2')?.addEventListener('click', () => window.goToStep(2));

applyMode('Structure + model', false);
updateLabels();
updateInteractiveLayers();
updateHighlight();
setButtonActive(2);
const narr = document.getElementById('demoNarration');
if (narr) narr.innerHTML = `<b>${steps[2].title}</b><br>${steps[2].narration}`;
// @FIGURE_CODE_END

